'use strict';
let liveTelemetry=null,readiness=null;
document.querySelector('[value=current]').textContent='Observações reais · inundação por validar';
const renderTelemetryBefore=render;render=function(){renderTelemetryBefore();let current=$('view').value==='current';let pilot=document.getElementById('pilot-panel');if(pilot)pilot.hidden=current;if(current)for(let id of ['pilot-flood','pilot-parishes'])if(map?.getLayer(id))map.setLayoutProperty(id,'visibility','none');if(!liveTelemetry)return;if(current){
 for(let id of ['pilot-flood','pilot-parishes'])if(map.getLayer(id))map.setLayoutProperty(id,'visibility','none');
 $('legend').innerHTML='<b>Observações reais APA / SNIRH</b><p>● Azul: estação com medição recente. ● Cinzento: antiga ou sem medição.</p><small>A régua mede altura local; não determina sozinha a mancha. Sinalização atual das freguesias aguarda calibração hidráulica e reconciliação de cotas.</small>';
 document.querySelector('.map-note').textContent='Medições reais ligadas · mancha atual ainda não validada · hipótese Q10 em vista separada';
 }};
function telemetryPopup(p){let s=liveTelemetry.stations.find(s=>s.id===p.id);if(!s)return '';return '<b>'+E(s.name)+'</b><p>'+E(s.river)+' · '+E(s.basin)+'</p>'+s.series.map(q=>{let r=q.latest;if(!r)return '<p>'+E(q.quantity)+': sem observação</p>';let title={level_m:'Nível na régua',elevation_m:'Cota publicada',flow_m3s:'Caudal',outflow_m3s:'Caudal efluente',inflow_m3s:'Caudal afluente',storage_percent:'Armazenamento'}[q.quantity];return '<p><b>'+title+': '+num(r.value,2)+' '+E(q.unit)+'</b><br>'+date(r.observed_at)+' · '+(C.fresh(r.observed_at)?'recente':'antiga')+'</p>';}).join('')+'<p>Hora interpretada em Europe/Lisbon; fonte sem fuso explícito. Referência vertical por confirmar; altura de régua não é altitude.</p><a href="'+E(s.source_url)+'" target="_blank" rel="noopener">Ver observações oficiais ↗</a>';}
async function loadTelemetry(){let [t,g,r]=await Promise.all([get('snirh-telemetry.json'),get('snirh-observations.geojson'),get('national-readiness.json')]);liveTelemetry=t;readiness=r;
 for(let f of g.features)f.properties.fresh=t.stations.find(s=>s.id===f.properties.id)?.series.some(p=>p.latest&&C.fresh(p.latest.observed_at))||false;
 if(!map.getSource('snirh-live')){map.addSource('snirh-live',{type:'geojson',data:g});map.addLayer({id:'snirh-live',type:'circle',source:'snirh-live',paint:{'circle-radius':6,'circle-color':['case',['get','fresh'],'#007da3','#969fa5'],'circle-stroke-color':'#fff','circle-stroke-width':2}});map.on('click','snirh-live',e=>new maplibregl.Popup({maxWidth:'310px'}).setLngLat(e.lngLat).setHTML(telemetryPopup(e.features[0].properties)).addTo(map));let label=document.createElement('label');label.innerHTML='<input type="checkbox" id="snirh-toggle" checked> Níveis, caudais e descargas · APA/SNIRH';document.querySelector('fieldset').append(label);$('snirh-toggle').onchange=()=>map.setLayoutProperty('snirh-live','visibility',$('snirh-toggle').checked?'visible':'none');let panel=document.createElement('div');panel.id='telemetry-panel';panel.className='notice';document.querySelector('.notice').before(panel);}else map.getSource('snirh-live').setData(g);
 let s=t.stations.find(s=>s.id==='1627759222'),h=s?.series.find(p=>p.quantity==='level_m')?.latest,q=s?.series.find(p=>p.quantity==='flow_m3s')?.latest;let reservoirs=['1627743384','1627759328','1627758668','1627743374'].map(id=>t.stations.find(s=>s.id===id)).filter(Boolean);
 $('telemetry-panel').innerHTML='<b>Medições reais · APA / SNIRH</b><p>'+g.features.filter(f=>f.properties.fresh).length+' de '+t.catalogue_count+' estações com medições recentes. Recolha: '+date(t.retrieved_at)+(t.collection_status==='connected'?'':' · recolha parcial ou indisponível')+'.</p><p><b>Santa Clara: '+(h?num(h.value,2)+' m na régua · '+date(h.observed_at):'nível indisponível')+'</b><br>Zero da régua: 15,45 m (SNIRH). '+(q?'Caudal: '+num(q.value)+' m³/s.':'Caudal local: sem observação publicada.')+'</p><details><summary>Descargas do sistema Mondego</summary>'+reservoirs.map(s=>{let p=s.series.find(p=>p.quantity==='outflow_m3s')?.latest;return '<p><b>'+E(s.name)+'</b>: '+(p?num(p.value,2)+' m³/s · '+date(p.observed_at):'efluente sem medição')+'</p>';}).join('')+'<p>Aguieira e Raiva estão em cascata: não se somam descargas. Ausência de medição não é descarga zero.</p></details><p><b>Calibração ainda não aceite.</b> Histórico Santa Clara 2016–2025: '+r.coimbra.calibration_data.daily_level_count+' níveis diários e '+r.coimbra.calibration_data.usable_same_station_daily_pairs+' pares nível–caudal. Falta reconciliar a referência vertical com o terreno.</p><button id="live-coimbra">Ver medições de Coimbra</button> <a href="report.html#snirh-integration">Resultados e expansão ↗</a>';$('live-coimbra').onclick=()=>map.fitBounds([[-8.5,40.16],[-7.96,40.44]],{padding:40});render();}
const telemetryReloadBefore=reload;reload=async function(){await telemetryReloadBefore();try{await loadTelemetry();}catch(e){document.querySelector('.map-note').textContent='Recolha SNIRH indisponível · consultar datas originais';}};
